/**
 * API utility functions for backend communication
 */

const API_BASE_URL = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8000';

export interface ApiError {
  detail: string;
}

/**
 * Get auth token from localStorage (if using auth)
 */
function getAuthToken(): string | null {
  if (typeof window === 'undefined') return null;
  return localStorage.getItem('auth_token');
}

/**
 * Make authenticated API request
 */
async function apiRequest<T>(
  endpoint: string,
  options: RequestInit = {}
): Promise<T> {
  const token = getAuthToken();
  const headers: HeadersInit = {
    'Content-Type': 'application/json',
    ...options.headers,
  };

  if (token) {
    headers['Authorization'] = `Bearer ${token}`;
  }

  const response = await fetch(`${API_BASE_URL}${endpoint}`, {
    ...options,
    headers,
  });

  if (!response.ok) {
    const error: ApiError = await response.json().catch(() => ({
      detail: `HTTP ${response.status}: ${response.statusText}`,
    }));
    throw new Error(error.detail || 'API request failed');
  }

  return response.json();
}

/**
 * Upload resume file
 */
export async function uploadResume(file: File): Promise<{
  status: string;
  resume_id: string;
  score: number;
  message: string;
  resume_data?: any;
}> {
  const token = getAuthToken();
  const formData = new FormData();
  formData.append('resume', file);

  const headers: HeadersInit = {};
  if (token) {
    headers['Authorization'] = `Bearer ${token}`;
  }

  const response = await fetch(`${API_BASE_URL}/api/v1/resume/upload`, {
    method: 'POST',
    headers,
    body: formData,
  });

  if (!response.ok) {
    const error: ApiError = await response.json().catch(() => ({
      detail: `HTTP ${response.status}: ${response.statusText}`,
    }));
    throw new Error(error.detail || 'Failed to upload resume');
  }

  return response.json();
}

/**
 * Get resume by ID
 */
export async function getResume(resumeId: string) {
  return apiRequest(`/api/v1/resume/${resumeId}`);
}

/**
 * Get latest resume for current user
 */
export async function getLatestResume() {
  // First get list of resumes, then get the latest one
  const resumes = await apiRequest<Array<{ id: string; created_at: string }>>(
    '/api/v1/resume/'
  );
  if (resumes.length === 0) {
    return null;
  }
  // Get the most recent one
  const latest = resumes[0];
  return getResume(latest.id);
}

/**
 * Get dashboard data
 */
export async function getDashboard(userId: string) {
  return apiRequest(`/api/v1/dashboard/${userId}`);
}

